function PTNL_Do()
	if GetLevel() < 35 then return end
	local n = HaveEventItemCount(39) or 0
	if n < PTNL_NEED then
		Talk(1, "no", PTNL_HEAD .. "Ta c\199n 3 c\169y <color=yellow>Li\212u M\233c<color> \174\211 d\249ng nh\181 m\237i, \174\230i l\185i 1 t\243i <color=yellow>H\185t th\199n b\221<color>. Ng\173\172i m\237i c\227 " .. n .. " c\169y.")
