	end
	if CalcFreeItemCellCount() < 1 then
		Talk(1, "no", PTNL_HEAD .. "H\181nh trang c\199n \221t nh\202t 1 \171 tr\232ng \174\211 nh\203n H\185t th\199n b\221.")
		return
	end
	local a = AddEventItem(48)
	if not a or a <= 0 then
		Talk(1, "no", PTNL_HEAD .. "H\181nh trang c\199n \221t nh\202t 1 \171 tr\232ng \174\211 nh\203n H\185t th\199n b\221.")
		return
	end
	local d = 0
	local i = 1
	while i <= PTNL_NEED do
		d = d + (DelEventItem(39) or 0)
		i = i + 1
	end
	if d < PTNL_NEED then
		DelEventItem(48)
		i = 1
		while i <= d do AddEventItem(39) i = i + 1 end
		Talk(1, "no", PTNL_HEAD .. "Kh\171ng l\202y \174\241 Li\212u M\233c, \174\183 tr\182 l\185i \174\229 cho ng\173\172i.")
		return
	end
	Msg2Player("Nh\203n \174\173\238c 1 t\243i H\185t th\199n b\221. Mang \174\213n T\250 B\181 \235 Tri\210u Ca \174\211 \174\230i M\199m c\169y (Thi\170n Th\244).")
	Talk(1, "no", PTNL_HEAD .. "\167\169y l\181 1 t\243i H\185t th\199n b\221. H\183y mang \174\213n <color=green>T\250 B\181<color> \235 Tri\210u Ca, n\181ng bi\213t c\184ch gieo tr\229ng.")
end
